import os

print("CWD:", os.getcwd())
print("Files:", os.listdir("."))

path = "budget.xlsx"
if not os.path.exists(path):
    raise SystemExit("budget.xlsx not found")

try:
    import openpyxl
    print("openpyxl version:", openpyxl.__version__)
    wb = openpyxl.load_workbook(path, data_only=False)
    print("Sheets:", wb.sheetnames)
    for ws in wb.worksheets:
        print(f"\n=== Sheet: {ws.title} ({ws.max_row} rows x {ws.max_column} cols) ===")
        for row in ws.iter_rows():
            vals = [(c.coordinate, c.value) for c in row if c.value is not None]
            if vals:
                print(vals)
except ImportError:
    print("NO_OPENPYXL")

import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("Archive entries:")
for n in z.namelist():
    print("  ", n)

# shared strings
shared = []
if "xl/sharedStrings.xml" in z.namelist():
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        shared.append(text)
print("\nShared strings:", shared)

# workbook sheet list
wb = ET.fromstring(z.read("xl/workbook.xml"))
sheets = wb.find("m:sheets", NS)
for s in sheets.findall("m:sheet", NS):
    print("Sheet:", s.get("name"), "rid:", s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))

# rels
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
relmap = {}
for rel in rels:
    relmap[rel.get("Id")] = rel.get("Target")
print("Rels:", relmap)

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters, row = m.group(1), int(m.group(2))
    c = 0
    for ch in letters:
        c = c * 26 + (ord(ch) - 64)
    return row, c

for s in sheets.findall("m:sheet", NS):
    name = s.get("name")
    rid = s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
    target = relmap.get(rid, "")
    if not target.startswith("xl/"):
        target = "xl/" + target.lstrip("/")
    sheet_root = ET.fromstring(z.read(target))
    grid = {}
    for c in sheet_root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
        ref = c.get("r")
        t = c.get("t")
        v = c.find("m:v", NS)
        val = None
        if v is not None:
            if t == "s":
                val = shared[int(v.text)]
            elif t == "str" or t == "inlineStr":
                val = v.text
            else:
                val = v.text
        isel = c.find("m:is", NS)
        if isel is not None:
            val = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        grid[ref] = val
    print(f"\n=== Sheet: {name} ===")
    rows = {}
    for ref, val in grid.items():
        r, cidx = col_to_idx(ref)
        rows.setdefault(r, {})[cidx] = val
    for r in sorted(rows):
        row = rows[r]
        maxc = max(row)
        print(r, [row.get(c) for c in range(1, maxc + 1)])

